globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-25 11:03:34 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"楽天証券、約441万件の個人情報漏えいを確認　168万口座の資産残高も流出","url":"https://japan.cnet.com/article/35255354/","source":"Hatena","published_at":"2026-11-25 07:17","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券で約441万件の個人情報漏えい、資産残高も流出","summary":"楽天証券は、第三者による不正アクセスにより、約441万件の個人情報が漏えいしたと発表しました。氏名や住所、電話番号に加え、約168万口座の資産残高情報も含まれています。\n\n第1報の調査から範囲が拡大し、性別や国籍、アンケート情報なども流出が判明しました。現時点でパスワードや暗証番号の漏えい、不正取引は確認されていませんが、金融庁から報告徴求命令を受けています。セキュリティ体制の強化と再発防止策の策定が急務となっています。","importance":9},{"title":"「AIがリーマン予想を証明したらどう感じるか？」と約1年半にわたって数学者たちに聞いてきたインタビューを振り返る","url":"https://gigazine.net/news/20261124-riemann-hypothesis-mathematician/","source":"Hatena","published_at":"2026-11-24 20:03","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIによるリーマン予想証明、数学者たちの「理解」を巡る議論","summary":"Anthropicの研究者らがClaudeを用いて一般化リーマン予想を証明したと発表しました。これを受け、数学者たちの間で「AIが人間には理解不能な証明を生み出した場合、それをどう評価すべきか」という議論が活発化しています。\n\n証明の正しさが形式的に検証可能であっても、概念的な明快さや美しさを求める数学者からは、AIとの協力関係の重要性が指摘されています。テレンス・タオ氏らは、AIを単なる証明生成ツールではなく、複雑な証明を分解・解釈し、人間と協力して新しい数学を切り拓くパートナーとして活用する未来を展望しています。","importance":10},{"title":"個人開発 with AI","url":"https://zenn.dev/holygrail/scraps/dec6ae85d06b4f","source":"Hatena","published_at":"2026-11-25 07:02","genre":"web","genre_label":"Web開発・言語","headline":"AIエージェントを活用した個人開発のワークフロー","summary":"個人開発者がAIエージェントを駆使して開発効率を最大化する手法についての解説記事。Claude Codeや自作のプラグインを活用し、設計から実装、レビュー、デプロイまでを自然言語で指示・自動化するワークフローを紹介しています。\n\n特にCloudflareを活用したインフラ運用とAIの親和性の高さが強調されており、監視やデプロイをAI経由で行うことで、少人数でも高度な開発体験を実現しています。AIを単なるコード生成ツールではなく、開発プロセス全体を管理するパートナーとして活用する実践的な知見です。","importance":7},{"title":"ロシア軍の死者４９万人超か、サイバー攻撃による流出データは「本物」と英報道…「５分に１人」戦死の計算","url":"https://www.yomiuri.co.jp/world/20261124-GYT1T00383/","source":"Hatena","published_at":"2026-11-25 00:56","genre":"other","genre_label":"総合・その他IT","headline":"ロシア軍の戦死者が49万人超か、流出データ検証で判明","summary":"英BBCは、サイバー攻撃により流出したロシア統計局のデータを検証し、ロシア軍の戦死者が少なくとも49万334人に上ると報じました。侵略開始から今年9月までの記録が含まれており、約5分に1人が戦死している計算となります。\n\nデータには戦闘による死者や行方不明者の内訳も詳細に記録されており、特に18〜34歳の男性の死亡状況が根本的に変化している実態が浮き彫りになりました。プーチン政権が多大な犠牲を顧みず侵略を継続している現状が、公的データの裏付けによって改めて示された形です。","importance":7},{"title":"Rails: 37signalsのコード品質を支える独自のエンジニアリング戦略（翻訳）｜TechRacho by BPS株式会社","url":"https://techracho.bpsinc.jp/hachi8833/2026_11_24/161424","source":"Hatena","published_at":"2026-11-24 17:35","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"37signalsのコード品質を支える独自のエンジニアリング戦略","summary":"37signalsのプロダクトがなぜ高品質でクリーンなのかを、同社のエンジニアリング戦略から分析した翻訳記事。「企業規模を拡大しない」「機能を容赦なく絞り込む」「優秀な人材の確保」という3つの柱が、好循環を生み出している。\n\n多くの企業が陥る「機能追加＝利益増」という先入観を捨て、コードベースを小さく保つことで、少人数のエンジニアでも深いレビューと高品質なメンテナンスが可能になる。持続可能な開発組織を目指すための重要な示唆に富んだ内容である。","importance":8},{"title":"ずっしり重い新型ウォークマン　歴代最高65万円なぜここまで高級化：朝日新聞","url":"https://www.asahi.com/articles/ASVCN2QXSVCNULFA01XM.html","source":"Hatena","published_at":"2026-11-25 08:35","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"ソニー新型ウォークマン、歴代最高65万円の高級化戦略","summary":"ソニーが発売する新型ウォークマンの旗艦モデルが、約65万5千円という歴代最高額で登場します。前モデルから26万円の大幅な値上げとなり、市場の注目を集めています。\n\n価格高騰の背景には、材料費や人件費の上昇、円安といった経済的要因に加え、音質向上のための銅素材の多用や、デジタル・アナログ分離のコンデンサー搭載など、妥協のない仕様へのこだわりがあります。音楽愛好家向けのハイエンド製品として、付加価値を極限まで高める戦略が取られています。","importance":4},{"title":"当社お客様の情報漏えいに関するお詫びとお知らせ（第2報）:楽天証券","url":"https://www.rakuten-sec.co.jp/web/info/info20261124-04.html","source":"Hatena","published_at":"2026-11-24 22:06","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券、約441万件の個人情報漏洩を公表（第2報）","summary":"楽天証券は、顧客情報の漏洩に関する第2報を発表しました。調査の結果、氏名、生年月日、住所、電話番号などを含む約441万件の個人情報が外部に持ち出されたことが判明しました。これには口座保有者だけでなく、未開設者の情報も含まれます。\n\nなお、ログインパスワードや取引暗証番号の漏洩は確認されておらず、現時点で不正アクセスや不正取引の被害も報告されていません。同社は関係各所と連携し、原因究明とセキュリティ対策の強化を継続するとしています。","importance":9},{"title":"34年目の秀丸エディタと、AIの距離感　「正直皆どんな目的で使ってるかよく分かりません」 - レバテックLAB","url":"https://levtech.jp/media/detail_973/","source":"Hatena","published_at":"2026-11-25 09:58","genre":"other","genre_label":"総合・その他IT","headline":"34年目の秀丸エディタ、AI活用への慎重な距離感","summary":"1993年公開の老舗テキストエディタ「秀丸エディタ」の開発元であるサイトー企画へのインタビュー記事。エディタ本体へのAI機能搭載には慎重な姿勢を見せる一方、社内開発ではClaude Codeを活用し、30年分のソースコード解析やバグ発見に役立てている実態が明かされました。\n\n開発陣は、AIが生成するコードの正確性や、実行環境に依存するUIの挙動には依然として課題があるとしつつも、補助ツールとしての有用性は認めています。ユーザーからのAI機能への要望が少ないこともあり、あくまで「道具」として賢く使い分けるスタンスを貫いています。","importance":5},{"title":"「Claude」で作ったアプリをMac／Windowsにインストール可能に　全プランでβ提供","url":"https://www.itmedia.co.jp/news/article/2611/25/2000003431/","source":"Hatena","published_at":"2026-11-25 10:11","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claudeで作成したアプリをMac/Windowsにインストール可能に","summary":"Anthropicは、AIアシスタント「Claude」で生成した「アーティファクト」を、MacおよびWindows向けのデスクトップアプリとしてインストールできる機能「Install as app」を全プラン向けにβ提供開始しました。\n\nこの機能により、Claude上で作成したWebページやツールを専用ウィンドウで動作させることが可能になります。通知機能やメニューバーへの表示、ファイル操作権限の付与にも対応しており、プログラミング知識がなくても実用的なデスクトップアプリを作成・共有できます。なお、利用にはClaudeデスクトップアプリの最新版が必要です。","importance":8},{"title":"JSConf JP 2026 参加ログ","url":"https://zenn.dev/aishift/articles/b6dbe1c0acc505","source":"Zenn","published_at":"2026-11-24 17:53","genre":"web","genre_label":"Web開発・言語","headline":"JSConf JP 2026参加ログ：サプライチェーン攻撃とAI時代のフロントエンド","summary":"JSConf JP 2026の参加レポート。サプライチェーン攻撃への多層的な備え、AI駆動開発におけるフロントエンド設計、ECMAScript仕様の深掘りなど、多岐にわたるセッションが共有された。\n\n特にnpmパッケージの乗っ取り事例を通じたセキュリティ対策の重要性や、Generative UIなどAI前提の設計思想が強く印象に残るテーマとして挙げられている。技術のトレンドを追いながら、銀の弾丸は存在しないという現実的なエンジニアリングの姿勢が強調された。","importance":8},{"title":"ワコムがMBOで株式非公開化へ、新事業やM&Aの加速を目指す","url":"https://pc.watch.impress.co.jp/docs/news/2158842.html","source":"Hatena","published_at":"2026-11-25 07:51","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"ワコムがMBOで株式非公開化へ、新事業とM&Aを加速","summary":"ペンタブレット大手のワコムは、経営陣が参加するMBO（経営陣による買収）により株式を非公開化する方針を発表しました。買付価格は1株1,030円で、上場廃止を経て経営の機動性を高める狙いです。\n\n非公開化の背景には、低価格製品の台頭や研究開発投資の増大があり、上場維持による短期的な業績配慮が成長の制約になっていると判断されました。今後はMBKパートナーズの支援を受け、次世代センサー技術「USM」や著作権保護サービスなどの新領域への投資とM&Aを加速させる方針です。","importance":6},{"title":"パスワード、全く自己管理する気がなくほぼ毎回リセットする運用の人が居てびびった→実はむしろこれが正しい運用であることをまだ人類は知らない","url":"https://togetter.com/li/2774455","source":"Hatena","published_at":"2026-11-24 18:12","genre":"other","genre_label":"総合・その他IT","headline":"パスワードを毎回リセットする運用はセキュリティ的に正しいのか","summary":"パスワードを覚えずに毎回リセット機能を利用するユーザーの運用方法が、セキュリティの観点から「実は合理的ではないか」と議論を呼んでいる。複雑なパスワードを記憶・管理する負担を避け、都度認証を行うことで、パスワード漏洩リスクを実質的に低減できるという視点である。\n\nこの運用は、利用頻度の低いサービスにおいて特に有効であり、人間がパスワードを記憶することの限界を指摘している。セキュリティの専門家からも、パスワード管理の煩雑さを解消する一つの解として一定の理解が得られており、パスワードレス認証への移行を促す文脈としても注目される。","importance":6},{"title":"歌った直後に30秒喋るだけ。カラオケの振り返りレポートを自動で作る仕組みを作った","url":"https://zenn.dev/semjin/articles/d6f543e4c75b07","source":"Zenn","published_at":"2026-11-25 02:23","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"歌唱の振り返りレポートを自動生成する仕組みを構築","summary":"カラオケ練習において、歌唱録音と直後の口頭レビューを組み合わせ、自覚と実測を突き合わせる振り返りレポート作成システムを構築した事例。歌詞照合の失敗を経て、音声認識を活用したレビュー分析へと転換した経緯が語られています。\n\n音程解析による「実測」と、歌唱直後の感想を文字起こし・感情分析した「自覚」を並べることで、再現性のある課題を特定可能にしました。技術的な試行錯誤を通じて、個人のスキルアップを支援するユニークなAI活用事例です。","importance":5},{"title":"公表資料から読む2026年10〜11月の情報漏えい23件：侵入経路はどこだったのか","url":"https://zenn.dev/shirochan/articles/f579abb8be4b1e","source":"Zenn","published_at":"2026-11-24 20:22","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"2026年10〜11月の情報漏えい23件、外部サービス経由の被害が顕著","summary":"10月28日から11月24日までに公表された情報漏えい事案23件を分析しました。この期間には1000万件を超える大規模な漏えいが5件発生しており、特にメール配信やWeb接客など、多くの企業が利用する外部サービスが攻撃の起点となるケースが目立ちます。\n\n原因が公表された事案では、管理画面の認証不備やAPI経由の不正操作、委託先のリモート接続環境の脆弱性が指摘されています。政府も緊急対策パッケージを示すなど対応を急いでおり、企業は自社だけでなく委託先を含めた基本的なセキュリティ対策の再点検が求められています。","importance":9},{"title":"Gemini 4 Neon を API で叩いて Claude Code・Codex CLI と比べた：65万トークンの超長文、費用、失敗","url":"https://zenn.dev/canly/articles/40e773759da8f8","source":"Zenn","published_at":"2026-11-24 17:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Gemini 4 Neonと他モデルの長文処理・コスト比較検証","summary":"GoogleのGemini 4 Neonを、Claude Opus 5.5およびGPT-6.2 Solと比較検証したレポート。65万トークンの超長文検索や数学・論理課題において、各モデルの性能とコスト、実行時間を測定した。\n\nGemini 4 Neonは長文脈でのグラフ探索などで高い性能を示したが、端末操作や細かいグラフ読み取りでは他モデルに劣る場面もあった。API利用におけるコストや思考トークンの挙動など、実務でモデルを選択する際の重要な判断材料が詳細にまとめられている。","importance":9},{"title":"はてブで投資系のブクマにスター付けまくってる謎のアカウント","url":"https://anond.hatelabo.jp/20261121084231","source":"Hatena","published_at":"2026-11-24 22:49","genre":"other","genre_label":"総合・その他IT","headline":"はてなブックマークで投資系記事にスターを乱発する謎のアカウント群","summary":"はてなブックマークにおいて、投資関連の記事に対して大量のスターを付与する謎のアカウント群が確認されました。アカウント名に「zhuge（諸葛）」が含まれるなど、同一人物による大量作成が疑われています。\n\n既にBANされているアカウントも存在しますが、同様の手法が繰り返されており、コミュニティ内では中国系ではないかといった推測や、通報の動きが広がっています。特定のジャンルを狙った不自然な反応が、プラットフォームの健全性に影響を与えています。","importance":3},{"title":"Claude Code の /ship を図解する","url":"https://zenn.dev/peoplex_blog/articles/claude-code-ship","source":"Zenn","published_at":"2026-11-24 15:30","genre":"web","genre_label":"Web開発・言語","headline":"Claude Codeの「/ship」スキルによるPR管理の自動化","summary":"Claude Codeに導入されたベータ版スキル「/ship」の仕組みを解説。PR作成からマージ直前までのプロセスを1つのセッションで完結させ、CIの監視やレビュー対応までを自動化する機能である。\n\n静的なPRを長期間見守る際の効率性や、勝手な操作を防ぐための安全策がプロンプトレベルで設計されている点が特徴。チーム開発におけるPR管理の負担を大幅に軽減する可能性がある一方、チーム固有の規約に合わせるための調整が必要となる。","importance":8},{"title":"楽天証券、顧客からの預かり資産残高168万件漏洩　性別や国籍も - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUB24AXS0U6A121C2000000/","source":"Hatena","published_at":"2026-11-25 06:28","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"不正アクセスによる顧客情報流出を巡って楽天証券は24日、追加の調査結果を公表した。","summary":"不正アクセスによる顧客情報流出を巡って楽天証券は24日、追加の調査結果を公表した。株式など顧客からの預かり資産残高の情報が約168万口座分漏洩した。\n\n性別や国籍など7項目の漏洩も新たに確認したと明らかにした。国内株や投資信託などの商品区分別での残高情報が漏れた。\n\n個別の保有銘柄や過去の取引履歴の情報は含まれない。これとは別に、顧客が口座開設時に自己申告した年収情報が約1.4万件、金融資産が約271万件漏洩した。\n\n自己申告は選択肢から選ぶもので、具体的金額ではないという。預かり資産に加えて氏名や住所、生年月日、電話番号などの個人情報が漏洩したのは約441万件（17日の前回発表時は最大447万件）だった。\n\n口座を持つ顧客の情報が約322万口座分、口座開設の手続きを途中でやめた人など未開設者の情報が約119万件だという。両者は重複している可能性もある。\n\n対象者は性別、国籍、ファクス番号なども漏洩したと新たに明らかにした。顧客コードとログインIDだけの漏洩は約1198万口座分（前回発表時は最大1125万口座）だった。","importance":5},{"title":"XIAO ESP32S3 Sense のカメラが映らない【中編】― ビット単位で追い詰める","url":"https://zenn.dev/kinotex/articles/453fc9ec8b602b","source":"Zenn","published_at":"2026-11-24 19:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"XIAO ESP32S3カメラ不良、ビット単位の解析で物理層の欠陥を特定","summary":"XIAO ESP32S3 Senseのカメラが正常に映らない問題を、ビット単位のデータ解析で特定しました。JPEGヘッダーの破損パターンを比較した結果、特定のデータ線（D0）がHIGHに持ち上がらない物理的な欠陥が原因であることを突き止めました。\n\n成功率を数値化するコマンドや、生データのビット統計を用いることで、オシロスコープなしでも不良の正体を特定する手法を確立しました。基板とカメラの入れ替え試験により、原因がカメラモジュール側にあることも判明。ハードウェアの不具合を論理的に追い詰めるプロセスが示されました。","importance":5},{"title":"「ドパガキ」が「Z世代の年間トレンド大賞」に　その意味とは　Simejiが選定","url":"https://japan.cnet.com/article/35255347/","source":"Hatena","published_at":"2026-11-24 19:13","genre":"other","genre_label":"総合・その他IT","headline":"Z世代トレンド大賞に「ドパガキ」、ショート動画依存を自虐","summary":"日本語入力アプリ「Simeji」が発表した「Z世代トレンドアワード2026」の年間トレンド大賞に、ショート動画を見続けてしまう自分を自虐的に表す言葉「ドパガキ」が選ばれました。短時間で次々と刺激を求める視聴習慣を笑い合う言葉として定着しています。\n\nヒト部門では歌謡コーラスグループ「モナキ」、モノ部門では玩具の「メロジョイ」が選出されました。Z世代のアンケート結果に基づいたこれらのトレンドは、デジタルネイティブ世代の消費行動や娯楽のあり方を反映しており、現代の若年層の関心事を知る指標となっています。","importance":3},{"title":"画像アップロードだけでサーバー乗っ取り？ 「Ghostscript」の脆弱性「Upload2Shell」／「WordPress」「Roundcube」などで攻撃成立、対策版への更新を","url":"https://forest.watch.impress.co.jp/docs/news/2158558.html","source":"Hatena","published_at":"2026-11-24 17:50","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Ghostscriptの脆弱性「Upload2Shell」によるサーバー乗っ取りリスク","summary":"GhostscriptのType 1フォント処理に起因する脆弱性「Upload2Shell」（CVE-2026-125396）が公開された。細工された画像ファイルを読み込ませるだけで、サンドボックスを回避して任意のコマンドが実行される危険性がある。\n\nWordPressやRoundcubeなど、画像処理の裏方としてGhostscriptを利用する多くのアプリが影響を受ける。すでに修正版がリリースされているため、サーバー管理者は早急なアップデートが推奨される。一見無害なファイルが攻撃の入り口になる典型的な事例である。","importance":9},{"title":"研究用のコードを、Claude Codeに任せてプロダクトにした","url":"https://zenn.dev/simulacra/articles/746128265d748c","source":"Zenn","published_at":"2026-11-24 12:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeを活用し研究用プロトタイプを10日でプロダクトへ昇華","summary":"AIインタビューサービス「うつしみ」の開発において、研究段階のプロトタイプをClaude Codeを用いて短期間で実用的なプロダクトへ作り直した事例です。少人数開発のため、設計・実装・レビューをAIに任せ、人間は判断に集中する体制を構築しました。\n\n開発では、worktreeによる作業分離や、設計原則を記述したCLAUDE.mdの活用、CIによる自動テストを徹底。エージェントの役割を細分化し、実装にはコスト効率の良いモデルを充てることで、速さと品質を両立させました。AIを単なるコーディング補助ではなく、開発プロセス全体を回すエンジンとして活用する手法が示されています。","importance":9},{"title":"AI時代の実践・形式検証入門","url":"https://docs.google.com/presentation/d/1s-ie7b1rD47NUkwSIvdDYCJfrHzWOl-rt1c2hSgeerM/mobilepresent?slide=id.p1","source":"Hatena","published_at":"2026-11-25 06:16","genre":"web","genre_label":"Web開発・言語","headline":"AI時代における実践的な形式検証入門","summary":"通常のテストでは見落としがちな複雑な仕様やルールの穴を、AIを活用して防ぐための形式検証ガイド。TLA+やTLCを用いたモデル検査の手法に焦点を当てています。\n\nAIが生成するコードや仕様の信頼性を担保するために、形式手法をどのように開発プロセスに組み込むべきかを解説。AI時代だからこそ、論理的な正しさを検証するスキルの重要性が増していることを示唆しています。","importance":6},{"title":"ソフトバンク、アイティメディアの売却検討か　2社「コメント控える」「決定した事実ない」","url":"https://www.itmedia.co.jp/news/article/2611/24/2000003427/","source":"Hatena","published_at":"2026-11-24 21:28","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"ソフトバンクによるアイティメディア売却検討報道、両社は否定","summary":"ソフトバンクが傘下のアイティメディアの売却を検討しているとの日本経済新聞の報道に対し、両社は「決定した事実はない」「コメントを控える」と回答しました。報道では、非中核事業の切り離しによるAI関連事業への経営資源集中が狙いとされています。\n\nソフトバンクはSBメディアホールディングスを通じてアイティメディア株式の過半数を保有しています。市場ではAIシフトを加速させるソフトバンクの動向に注目が集まっており、今回の報道はメディア事業の再編の可能性を示唆するものとして関心を集めています。","importance":6},{"title":"使わなくなったAndroidスマートフォンにPCのシステムステータスやAIエージェントの使用率など様々なウィジェットを表示させておくことができるAndroidアプリ「PhoneBox」がmacOSと日本語に対応。","url":"https://applech2.com/archives/20261124-phonebox-for-android-support-mac.html","source":"Hatena","published_at":"2026-11-24 13:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"使わなくなったAndroidをPCのシステムモニタにする「PhoneBox」がmacOS対応","summary":"PhoneBoxは、古いAndroid端末をUSBやWi-Fi経由でPCのサブディスプレイや操作パネルとして活用できるAndroidアプリです。これまでWindowsやLinuxに対応していましたが、最新アップデートでmacOSにも対応しました。\n\nApple Silicon MacのSMCからの温度取得や、カメラ・マイクの使用状況表示など、131種類のウィジェットと30種類のテンプレートが利用可能です。さらに日本語ローカライズも行われ、AIエージェントのセッション監視機能なども追加されており、余ったデバイスの有効活用に最適です。","importance":5},{"title":"三重県警 小学校元講師 AI生成の児童ポルノ画像所持で追送検 | NHKニュース","url":"https://news.web.nhk/newsweb/na/nd-20261124de80746","source":"Hatena","published_at":"2026-11-25 08:37","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AI生成の児童ポルノ画像所持で小学校元講師を追送検","summary":"三重県内の小学校元講師が、実在する少女の写真をもとに生成AIで作成された裸の画像を所持していたとして、児童ポルノ禁止法違反の疑いで追送検されました。\n\n生成AI技術の悪用による児童ポルノ問題は社会的な懸念となっており、法規制や捜査のあり方が問われています。本件は、AIによって生成された画像であっても、実在の人物を基にしたものは法的に厳しく処罰される対象であることを改めて示しました。","importance":7},{"title":"【ドパガキ向け】AI 時代の要求管理 ハンドブックを読もう","url":"https://zenn.dev/muroshima/articles/be47515ff9c16e","source":"Zenn","published_at":"2026-11-25 01:36","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"IPA「AI時代の要求管理ハンドブック」の重要ポイント解説","summary":"IPAが公開した「AI時代の要求管理ハンドブック」の要点をまとめた解説記事。AIシステム開発において、要望をそのまま実装するのではなく、目的の整理や要件への落とし込みが重要であると説いています。\n\nAI特有の確率的な振る舞いに対する安全策や、運用後の継続的な要件更新、人間による監視の重要性などが網羅されています。プロンプトエンジニアリングも要求工学の一部と位置づけ、AIエージェントを活用する場合でも、構造化された管理プロセスが必要であると結論づけています。","importance":8},{"title":"画面から「Kong 経由で送信」― APIキーを渡さずに役席が外部連携を代行する仕組み","url":"https://zenn.dev/kensudo1203/articles/bcd3ef26cce0ce","source":"Zenn","published_at":"2026-11-24 20:37","genre":"web","genre_label":"Web開発・言語","headline":"APIキーを渡さずに役席が外部連携を代行するKong活用術","summary":"銀行システムを想定した環境において、APIキーをブラウザに渡さずに役席者が外部連携を代行する仕組みを構築しました。Next.jsのサーバー側でキーを管理し、Kongを介してMuleSoftへリクエストを中継するアーキテクチャを採用しています。\n\n役席者のみが送信可能とする権限管理や、実行履歴の記録、CSRF対策を徹底。Kongのプラグインを活用し、外部連携先と同じ検証経路を通すことで安全性を確保しました。また、重複入金を防ぐ一意キーの生成や、エラー形式の統一により、堅牢かつ運用しやすい連携基盤を実現しています。","importance":7},{"title":"Rails Doctrineは一人で読むより、みんなで読むと面白い","url":"https://zenn.dev/luxiar/articles/33f3cefbdb5e26","source":"Zenn","published_at":"2026-11-24 11:00","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"「The Rails Doctrine」をチームで読むことで深まる設計思想の理解","summary":"Railsの設計思想をまとめた「The Rails Doctrine」をチームで読み合わせる読書会の取り組みを紹介しています。一人で読むと単なる「経典」として盲信しがちな内容も、当時の技術背景を知るベテランと議論することで、なぜその設計に至ったかの文脈が深く理解できます。\n\n特に「唯一のパラダイムはない」といった現代では当たり前の概念も、登場当時の技術的背景と照らし合わせることで、Railsの柔軟性と適材適所の考え方を再認識できます。チームで共有することで、技術選定や設計判断の質を高める効果が期待できます。","importance":4},{"title":"DuckDBで日次ETLを冪等にする。同じParquetを2回投入しても二重計上しない設計","url":"https://zenn.dev/chando_ra/articles/duckdb-idempotent-etl","source":"Zenn","published_at":"2026-11-24 22:13","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"DuckDBを用いた日次ETLの冪等性確保と二重計上防止設計","summary":"日次バッチ処理において、失敗時の再実行でデータが二重計上されるリスクを回避するため、DuckDBを用いた冪等なETL処理を設計しました。前日分の全件をParquetから読み込み、対象日の明細と集計をまとめて差し替える手法を採用しています。\n\nトランザクションを活用し、明細と集計を同時に更新することで、処理中断時も整合性を維持可能です。100万行規模のデータでも高速に処理でき、入力ファイルの版管理や重複チェックを組み合わせることで、再実行時の安全性を担保する実用的な設計となっています。","importance":8},{"title":"0.3秒で答えるAIは、暗算でつまずく ― Jev・OpenAI・Geminiの判断APIを165問で比べた","url":"https://zenn.dev/rehabforjapan/articles/decision-api-comparison","source":"Zenn","published_at":"2026-11-24 14:01","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"判断専用APIの性能比較：計算・規則問題におけるGeminiの優位性","summary":"Jev、OpenAI、Geminiの3社が提供する「判断専用API」を165問のテストで比較検証したレポート。文章の読み取りや振り分けでは3社とも高い精度を示したが、計算や規則の当てはめ問題で明確な差が出た。\n\nGeminiが計算・規則問題で最も高い正解率を記録し、他の2社を上回った。判断APIは文章生成を行わないため高速だが、複雑な計算を伴うタスクではモデルの論理的推論能力が結果を左右することが示された。業務利用におけるAPI選定の重要な指標となる。","importance":8},{"title":"設計書のないClassic ASP アプリを ASP.NET Core にマイグレーションしたときにやったこと","url":"https://zenn.dev/pomio/articles/2026-11-22_mig","source":"Zenn","published_at":"2026-11-24 17:51","genre":"web","genre_label":"Web開発・言語","headline":"設計書なしのClassic ASPをASP.NET Coreへ移行する際の戦略","summary":"設計書が存在しない約10万ステップのClassic ASPシステムを、5人体制で1年以内にASP.NET Coreへ移行したプロジェクトの記録。納期遵守を最優先し、「不具合を直さない」「最新技術を無理に追わない」「設計書を作らない」という割り切った方針を策定した。\n\nコード変換には生成AIを活用し、レビューで品質を担保する手法を採用。アーキテクチャ選定ではメンバーのスキルセットを考慮し、保守性を重視してDapperを採用するなど、現実的な判断が成功の鍵となった。技術的負債の返済よりも「動くシステムを完成させる」ことに特化した事例である。","importance":7},{"title":"JAXAに不正アクセス、地球観測データの利用者2000人の情報が漏洩 - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOSG244FZ0U6A121C2000000/","source":"Hatena","published_at":"2026-11-24 20:37","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"JAXAの地球観測データシステムに不正アクセス、2000人分流出","summary":"宇宙航空研究開発機構（JAXA）は、地球観測衛星データの公開システムが外部からの不正アクセスを受け、利用者2000人分のアカウント情報が漏洩したと発表しました。18日に被害を確認し、即座にシステムを停止しています。\n\n現在、影響範囲や攻撃の詳細について調査が進められており、再開のめどは立っていません。近年、スパコン「富岳」への攻撃など、日本の研究機関や重要インフラを標的としたサイバー攻撃が相次いでおり、セキュリティ対策の強化が急務となっています。","importance":8},{"title":"GoogleがAIの性能測定ツール「gBench」をオープンソース化","url":"https://gigazine.net/news/20261124-google-gbench-benchmarking-framework/","source":"Hatena","published_at":"2026-11-24 12:53","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"GoogleがAIモデルの性能測定フレームワーク「gBench」をオープンソース化","summary":"Googleは、GemmaなどのオープンモデルやLLM/VLMの性能を評価するためのベンチマークフレームワーク「gBench」をオープンソースとして公開しました。Pythonパッケージとして提供され、pipで簡単にインストール可能です。\n\ngBenchは86種類の評価スイートやエージェント向けベンチマーク、チャットテンプレートのチェック機能などを備えています。OpenAI互換APIをサポートしており、vLLMやOllama環境での動作が確認されています。開発者は自前のモデルを効率的に評価・比較できるようになります。","importance":8},{"title":"Git for Windows の connect.exe で SSH の上りが遅い原因を追った話","url":"https://zenn.dev/akarineren/articles/13ee3a909672c7","source":"Zenn","published_at":"2026-11-24 23:29","genre":"web","genre_label":"Web開発・言語","headline":"Git for WindowsのSSH通信遅延、原因はconnect.exeのポーリング処理","summary":"Git for Windowsに同梱されているconnect.exeを介したSSH通信において、上り速度が極端に遅い問題が発生しました。調査の結果、Windows環境におけるstdinのポーリング処理（selectとPeekNamedPipe）が原因で、タイマーのtick（約15.6ms）に起因する転送速度の上限が生じていることが判明しました。\n\n上流の修正版ではタイムアウト値が改善されていましたが、MSYS2側のパッケージが古かったため、PRを提出して解消しました。さらに、ポーリング自体を廃止してスレッドを用いたブロッキングI/Oに切り替えることで、Windows環境における通信性能の根本的な改善を実現しました。","importance":6},{"title":"AWS、DynamoDB互換データベースをローカルマシンで構築可能にするオープンソース「ExtendDB」がバージョン1.0に到達","url":"https://www.publickey1.jp/blog/26/awsdynamodbextenddb10.html","source":"Hatena","published_at":"2026-11-25 01:30","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"DynamoDB互換のローカルDB「ExtendDB」がv1.0に到達","summary":"AWSのNoSQLデータベース「Amazon DynamoDB」と互換性を持つオープンソース「ExtendDB」がバージョン1.0に到達しました。ローカルマシン上でDynamoDB環境を構築可能です。\n\nPostgreSQLやSQLiteなどをエンジンとして利用し、DynamoDBと同じSDKで操作できるため、開発やテスト環境の構築に最適です。クラウドとオンプレミスのハイブリッド環境や、既存のDynamoDBスキルを活かしたローカルアプリ開発において、高い有用性が期待されます。","importance":7},{"title":"RTX 5070 Ti 16GB で動くローカル LLM を 8 種類比べて、Claude から任せられそうな仕事とモデルを探った話","url":"https://zenn.dev/hikari_lab_dev/articles/ef4a3fe94b3b2f","source":"Zenn","published_at":"2026-11-24 11:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"RTX 5070 Ti環境でのローカルLLM 8種比較とClaudeとの役割分担","summary":"手元のGPU（VRAM 16GB）環境で8種類のローカルLLMを動かし、Claudeとの性能比較と役割分担を検証したレポートです。コード実装や事務作業などの課題を通じて、ローカルLLMが実用的な範囲を特定しました。\n\n結論として、仕様が明確なコード実装や定型的な事務作業はQwen3.8-27Bなどのローカルモデルに任せ、設計や判断を伴う複雑なタスクはクラウドのClaudeに任せるのが最適と判断されました。ローカルLLMの活用により、クラウドコストの削減と開発効率の向上が期待できます。","importance":8},{"title":"アップグレードで消えた暗黙の契約 ― Prisma 7 と DATE 列","url":"https://zenn.dev/jins/articles/413543b799a674","source":"Zenn","published_at":"2026-11-24 15:01","genre":"web","genre_label":"Web開発・言語","headline":"Prisma 7へのアップグレードで発生したDATE列の型推論問題","summary":"Prisma 6から7へのアップグレードにより、PostgreSQLのDATE列に対するクエリ結果が空になる不具合が発生した事例。原因はPrisma 7のアダプターがパラメーターの型を明示しなくなったことで、PostgreSQL側が型を誤って推論したことにあった。\n\n同じコードでもPrismaのバージョンによって通信内容が変化し、型推論の挙動が変わるという「暗黙の契約」が崩れたケース。ライブラリのアップデート時には、こうした低レイヤーの挙動変化にも注意を払う必要があるという教訓である。","importance":6},{"title":"CloudNative Days Winter 2026参加記","url":"https://zenn.dev/0st_ts/articles/97ddb35a5f8cc1","source":"Zenn","published_at":"2026-11-24 19:19","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CloudNative Days Winter 2026参加記、AI時代のインフラ運用","summary":"CloudNative Days Winter 2026に参加し、AIエージェントの認可課題やLLM推論基盤の構築、Kubernetesのスケジューリング技術について学びました。特にLINEヤフーのマルチテナント推論基盤におけるレート制限やルーティングの工夫が印象的です。\n\n開発組織における自律的なセキュリティ思考や、k6とOpenTelemetryを用いた性能改善の検証など、現場の知見が共有されました。AIの活用が広がる中で、インフラ側でゲートウェイやスケジューリングをどう最適化し、安全性を担保するかが今後の重要なテーマとなっています。","importance":6},{"title":"AIエージェントに仕事を任せてみた感想","url":"https://zenn.dev/xaiondata/articles/9bc2ad70475415","source":"Zenn","published_at":"2026-11-24 10:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントに仕事を任せて見えた「人間が担うべき役割」","summary":"AIエージェントに抽象的な知的作業を任せた経験から、AIの得意分野と人間が担うべき領域を整理した考察です。AIは知識量や実装速度で圧倒的ですが、優先順位付けや暗黙知の活用には限界があります。\n\n特に、ステークホルダーとの関係性や「肌感」に基づく判断はAIには渡せません。AIに主導権を渡すと全てのタスクを同列に扱ってしまうため、人間が「具体と抽象」を行き来し、全体像（Big Picture）を意識して判断を下すことが重要です。AIを使いこなすには、人間側のメタ認知能力がより強く求められます。","importance":9},{"title":"要件定義書のレビュー観点を、チェックリストにしてみた","url":"https://zenn.dev/vaonvn/articles/395e38023ae063","source":"Zenn","published_at":"2026-11-24 09:59","genre":"web","genre_label":"Web開発・言語","headline":"要件定義書のレビューを効率化する3段階チェックリスト","summary":"要件定義書のレビュー観点を「機械で確かめる」「LLMに1次レビューさせる」「人が見る」の3段階に分類したチェックリストを提案しています。これにより、レビューの効率化と品質向上を図ります。\n\n機械で確かめられる形式的な不備をCIで自動化し、論理的な矛盾をLLMに任せることで、人の時間は業務ルールや合意事項といった「人間にしか判断できない領域」に集中させます。プロンプト管理とスクリプトによる自動化を組み合わせることで、ドキュメントの鮮度と整合性を保つ実践的な手法です。","importance":7},{"title":"中古PCにProxmox VE 9.2を導入して個人開発用Staging環境を構築した記録","url":"https://zenn.dev/locu/articles/d71e8c4996a365","source":"Zenn","published_at":"2026-11-24 14:17","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Proxmox VE 9.2を用いた個人開発用Staging環境の構築","summary":"個人開発プロダクトのStaging環境を構築するため、中古PCにProxmox VE 9.2を導入した記録。VM単位でリソースを分離し、将来的な拡張性も考慮したインフラ構成を整えた。\n\nHyper-Vでの事前検証やVLAN設定、NVMeの認識トラブルなど、実機導入における具体的な課題と解決策がまとめられている。Kubernetes運用前のステップとして、安定した検証環境を構築するための現実的な選択肢としてProxmoxが活用されている。","importance":6},{"title":"MCPの記録ツールを追記だけで作ると、訂正のたびに重複が残る。AIは「消せない」と正直に言うが、集計は間違える","url":"https://zenn.dev/kentaro_tak/articles/mcp-logger-append-only-corrections","source":"Zenn","published_at":"2026-11-24 23:04","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MCPツール設計における「追記のみ」の限界とAIの訂正処理","summary":"AIエージェント（Claude Code）にGoogleスプレッドシートやDBへの記録を任せる際、ツールが「追記」しかできないと、訂正時に重複データが発生し集計が誤る問題が浮上しました。AIは訂正を試みますが、削除機能がない環境では矛盾を解消できません。\n\n実験の結果、削除機能（DELETE）や置き換え（UPSERT）を実装することで、AIは正確にデータを管理できるようになりました。特に1日1行の記録にはUPSERTが適しており、AIにシェル操作を許可せずとも、適切なツール設計を行うことでデータ整合性を保てることを示しました。","importance":7},{"title":"jQuery 4.1正式版がリリース、内部実装をquerySelectorAllに統一でより高速に。jQuery 3.x系最後となるjQuery 3.8も同時リリース","url":"https://www.publickey1.jp/blog/26/jquery_41queryselectoralljquery_3xjquery_38.html","source":"Hatena","published_at":"2026-11-25 01:30","genre":"web","genre_label":"Web開発・言語","headline":"jQuery 4.1正式版リリース、内部実装の刷新で高速化","summary":"JavaScriptライブラリ「jQuery」の最新版「4.1」が正式リリースされました。同時にjQuery 3.x系の最終版となる「3.8」も公開されています。\n\n4.1では内部実装をquerySelectorAllに統一し、処理の高速化を実現。レガシーブラウザのサポートを終了し、モダンブラウザに特化した開発体制へ移行します。今後は4.x系に一本化され、継続的な機能追加が行われる予定です。長年Web開発を支えてきたjQueryの大きな転換点となります。","importance":5},{"title":"自宅DNSサーバを遠隔で再起動したら45分戻らず、家のネットが止まった話","url":"https://zenn.dev/yowahada/articles/wyse-remote-reboot-hang","source":"Zenn","published_at":"2026-11-24 18:28","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"自宅DNSサーバの遠隔再起動でネットが遮断、復旧までの教訓","summary":"自宅のDNSサーバ（AdGuardHome）をSSHで遠隔再起動した際、機体が応答しなくなり約45分間インターネットが利用不能になったトラブルの記録。原因は特定できていないものの、DNSサーバが単一障害点となっていたことが被害を拡大させた。\n\n結論として、DNSサーバには必ず予備を用意すること、遠隔操作時は「戻らなかった場合」の物理的な復旧手段を想定しておくことの重要性が示された。また、OSの正常終了ログは確認できたため、今後は機体の応答性を監視する仕組みの必要性が浮き彫りとなった。","importance":5},{"title":"AIが書いた原稿は、チェックを全部通ったうえで日付を間違えていた — チェックは形を見て、中身は見ていない","url":"https://zenn.dev/sbkm/articles/0a8d9931015ba9","source":"Zenn","published_at":"2026-11-24 21:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI生成原稿のチェック体制、形式は通るが中身の誤りは防げず","summary":"AIを活用したポッドキャスト配信において、発表日や重複を機械的にチェックするゲートを設けても、中身の誤りがすり抜ける事例が多発しています。チェック機能が「日付の形式」や「語の重複」といった形式面しか見ていないことが原因です。\n\n日付の推測や「公表されていない」といった文脈の誤解は、AIが一次資料と突き合わせる手順を踏むことで初めて検知可能でした。形式的なチェックは補助に過ぎず、意味的な整合性を担保するには、AIによる高度な検証プロセスや人間による最終確認が不可欠であるという教訓が得られました。","importance":7},{"title":"[生成AI利用] ノートのグラフを three.js で「盆栽」にして、6回作り直して最初の形に戻った話","url":"https://zenn.dev/rezora/articles/20261125-kb-bonsai-threejs","source":"Zenn","published_at":"2026-11-25 01:05","genre":"web","genre_label":"Web開発・言語","headline":"three.jsでノートのグラフを「盆栽」として可視化","summary":"Obsidianのノートリンクをthree.jsを用いて3Dの「盆栽」として可視化するプロジェクトの制作記録。Claude Codeをパートナーに、6回の作り直しを経て完成に至った経緯がまとめられています。\n\nInstancedMeshによる葉の描画や、シェーダーを用いたネオン表現など、技術的な工夫が凝らされています。最終的に「情報は少ないほうが模型として美しい」という結論に達し、目的を明確にすることの重要性を説いています。ARグラスでの表示も視野に入れた、技術とデザインの融合事例です。","importance":5},{"title":"Copilot Studioのエージェント開発をClaude Codeにどこまで任せられるか試した","url":"https://zenn.dev/upgradetech/articles/a9a1637d3071c1","source":"Zenn","published_at":"2026-11-24 18:24","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeを活用したCopilot Studioエージェント開発の可能性","summary":"MicrosoftのCopilot Studioでエージェントを開発する際、画面操作の手間や変更履歴の管理が煩雑になる課題に対し、Claude Codeを用いた自動化を試みた事例。PAC CLIやPower Automateプラグインを組み合わせ、自然言語による指示でエージェント構築やフロー作成を効率化する手法を検証した。\n\n結果として、ファイルの編集やコマンド実行などの実作業はAIに任せられるものの、環境選択や承認、最終的な品質判断には人間の介在が不可欠であることが判明した。ツールを組み合わせることで開発体験は向上するが、完全な自動化にはまだ距離がある。","importance":7},{"title":"「昨日ゲーセンで千円と自販機で150円」を家計簿の2行にする ― Apps Script で日本語の金額・日付を読む","url":"https://zenn.dev/moneystock/articles/gas-kakeibo-japanese-amount-parser","source":"Zenn","published_at":"2026-11-24 16:29","genre":"web","genre_label":"Web開発・言語","headline":"Apps Scriptで自然言語の家計簿入力を効率化する実装術","summary":"GoogleスプレッドシートとApps Scriptを用い、自然言語で入力された支出情報を家計簿に自動記録する仕組みの構築記録。すべてをLLMに任せず、正規表現と辞書によるルールベース処理を優先することで、高速かつ安定した動作を実現した。\n\n日付や金額の曖昧な表現をルールで解決し、自信がない場合のみGemini APIを呼び出すハイブリッドなアプローチを採用。家計簿のような定型的な入力において、AIとルールベースを適材適所で使い分けることの有効性が示された。","importance":5},{"title":"変なTinyLMを12匹育てたら、自作GPTの組み合わせが条件つきでQwen2.5-0.5Bを上回った話","url":"https://zenn.dev/emilia_lab/articles/tiny-lm-12-vs-llm","source":"Zenn","published_at":"2026-11-24 15:36","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"TinyLMの育成と自作GPTによるQwen2.5-0.5B超えの試み","summary":"「睡眠」「忘却」などのユニークな仕組みを持つ小さな言語モデル（TinyLM）を育成し、その性能を評価した実験記録。最終的に自作の文字単位GPTを組み合わせることで、特定の評価条件においてQwen2.5-0.5Bを上回る予測成績を達成した。\n\n「睡眠」が記憶の忘れ防止に寄与することや、キャッシュ的な手法が予測に有効であることなど、LLMの基礎的な仕組みを小規模モデルで検証する面白さが示されている。モデルの規模と性能の関係を深く理解するための興味深いアプローチである。","importance":7}]};
